            if '#[cfg(test)]' in line:
                in_test = True
            if in_test:
                continue
            if '.unwrap()' in line and '///' not in line and '//!' not in line:
                # Skip doc comments
                stripped = line.strip()
                if stripped.startswith('///') or stripped.startswith('//!') or stripped.startswith('//'):
                    continue
                print(f'{path}:{i}: {line.strip()}')
