                if allow_quit {
                    if self.clear {
                        render.clear()?;
                    } else {
                        term.clear_last_lines(paging.capacity)?;
                    }

                    term.show_cursor()?;
                    term.flush()?;

                    return Ok(None);
                }
            }
            Key::ArrowUp | Key::BackTab | Key::Char('k') => {
                if sel == !0 {
                    sel = self.items.len() - 1;
                } else {
                    sel = ((sel as i64 - 1 + self.items.len() as i64)
                        % (self.items.len() as i64)) as usize;
